<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Rankings</title><link rel='stylesheet' href='/assets/css/ui.css'><link rel='stylesheet' href='/assets/css/components.css'><link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css'><style>thead th{position:sticky;top:0;background:#0f172a}</style></head><body><script src='/assets/js/ui.js'></script><script>
UX.shell('/rankings',`<div class='hero'><h2>Global Leaderboard</h2><div style='display:flex;gap:8px'><input id='q' class='search' placeholder='Search'><select id='sort' class='search'><option value='desc'>Desc</option><option value='asc'>Asc</option></select></div></div><div id='top3' class='grid cols-3'></div><div class='glass-card' style='margin-top:10px'><div class='tabs'><button class='tab active' data-t='regions'>Regions</button><button class='tab' data-t='countries'>Countries</button><button class='tab' data-t='players'>Players</button></div><div class='accordion open' id='acc'><div class='acc-h'>Leaderboard Table</div><div class='acc-b'><table class='table'><thead><tr><th>#</th><th>Name</th><th>Score</th></tr></thead><tbody id='rows'><tr><td colspan='3'><div class='skeleton'></div></td></tr></tbody></table></div></div></div>`);
let tab='regions', data={regions:[],countries:[],players:[]};
const color=v=>v<=2?'stat-red':v<=5?'stat-yellow':'stat-green';
(async()=>{const d=await UX.api('/api/stats/dashboard');data.regions=d.top_regions||[];data.countries=d.top_countries||[];data.players=(d.top_players||[]).map(x=>({id:x.id,name:x.username,score:Number(x.level||0),xp:Number(x.xp||0),nation_name:x.nation_name||'',nation_flag_url:x.nation_flag_url||''}));render();})();
function render(){const s=(q.value||'').toLowerCase(),asc=sort.value==='asc';let arr=(data[tab]||[]).map(x=>({...x,_score:Number(x.score||x.total_score||0),_name:x.name||x.country_name||x.name,_sub:tab==='players'?`Lv ${Number(x.score||0)} • XP ${UX.fmt(x.xp||0)}`:''})).filter(x=>x._name.toLowerCase().includes(s));arr.sort((a,b)=>asc?a._score-b._score:b._score-a._score);top3.innerHTML=arr.slice(0,3).map((r,i)=>`<div class='glass-card pulse'><h3>${['🥇','🥈','🥉'][i]}</h3><div>${r._name}</div><div class='kpi'>${UX.fmt(r._score)}</div></div>`).join('');rows.innerHTML=arr.map((r,i)=>{const href=tab==='regions'?`/region/${r.id}`:tab==='countries'?`/country/${r.id}`:`/player/${r.id}`;return `<tr><td>${i+1}</td><td><a href='${href}'>${r._name}</a><br><small class='sub'>${r._sub||''}</small></td><td class='${color(r._score)}'>${UX.fmt(r._score)}</td></tr>`;}).join('');}
document.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>{tab=b.dataset.t;document.querySelectorAll('[data-t]').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();});q.oninput=render;sort.onchange=render;document.querySelector('.acc-h').onclick=()=>acc.classList.toggle('open');
</script></body></html>
